-- AniDex demo seed: made-up titles, studios and history for the public static demo.
--
-- Every title, studio, note and link here is invented. No real anime titles, no
-- real cover art (covers are generated by demo/make_covers.py and served from
-- /static/demo-covers/<id>.svg), no third-party hosts (links use example.invalid).
-- Ids start at 900001, far above anything the real app stores for this demo.
--
-- Dates are relative to the day the demo is built, so /stats, /stats/wrapped and
-- /upcoming always have this-year, last-year and upcoming data.
--
-- Apply after schema.sql and after the demo user has registered (the first account
-- becomes admin):
--   psql "$DATABASE_URL" -v email="demo@example.invalid" -f demo/seed.sql
-- demo/record.mjs and tests/test_demo_seed.py bind :'email' the same way.

BEGIN;

