INSERT INTO anime (id, title_romaji, title_english, format, status, episodes, duration,
                   season, season_year, genres, tags, studios, average_score,
                   cover_image_url, description, external_links)
SELECT v.id, v.romaji, v.english, v.format, v.status, v.episodes, v.duration,
       v.season, EXTRACT(YEAR FROM current_date)::int - v.years_ago,
       v.genres::jsonb, v.tags::jsonb,
       jsonb_build_array(jsonb_build_object('name', v.studio, 'isMain', true)),
       v.avg,
       '/static/demo-covers/' || v.id || '.svg',
       v.descr,
       COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
               'site', s, 'url', 'https://stream.example.invalid/' || v.id))
           FROM unnest(v.sites) AS s
       ), '[]'::jsonb)
