-- Starlight Demolition Crew and Winter Automaton are a sequel pair.
UPDATE anime SET relations = jsonb_build_array(jsonb_build_object(
    'id', 900008, 'title', 'Winter Automaton', 'cover', '/static/demo-covers/900008.svg',
    'format', 'TV', 'relation_type', 'SEQUEL'))
WHERE id = 900001;
UPDATE anime SET relations = jsonb_build_array(jsonb_build_object(
    'id', 900001, 'title', 'The Starlight Demolition Crew', 'cover', '/static/demo-covers/900001.svg',
    'format', 'TV', 'relation_type', 'PREQUEL'))
WHERE id = 900008;

-- ── The demo user's library ───────────────────────────────────────────────
-- finish: 'this' = this calendar year (day N, clamped to today), 'prior' = last
-- year (day N), 'old' = three years ago (day N), NULL = not finished.
-- started_days: days before finish (or before today when unfinished).
UPDATE users SET display_name = 'Demo Viewer' WHERE email = :'email';

INSERT INTO library_entries (user_id, anime_id, status, score, progress, repeat_count,
                             start_date, finish_date)
SELECT u.id, v.anime_id, v.status, v.score, v.progress, v.repeat_count,
       COALESCE(f.finish, current_date) - v.started_days,
       f.finish
FROM users u
CROSS JOIN (VALUES
  (900001, 'COMPLETED', 4.5, 12, 1, 'this',  20,  30),
  (900002, 'COMPLETED', 5.0, 24, 2, 'prior', 300, 60),
  (900003, 'COMPLETED', 3.5, 13, 0, 'this',  45,  20),
  (900004, 'WATCHING',  NULL, 6, 0, NULL,    NULL, 40),
  (900005, 'COMPLETED', 4.5, 1,  0, 'this',  60,  0),
  (900006, 'COMPLETED', 3.0, 12, 0, 'prior', 120, 25),
  (900007, 'DROPPED',   2.0, 5,  0, NULL,    NULL, 200),
  (900008, 'COMPLETED', 4.0, 10, 0, 'this',  95,  14),
  (900009, 'COMPLETED', 4.0, 8,  0, 'this',  110, 3),
  (900010, 'PAUSED',    3.5, 7,  0, NULL,    NULL, 150),
  (900011, 'COMPLETED', 2.5, 12, 0, 'old',   200, 30),
  (900012, 'REPEATING', 4.5, 5,  1, NULL,    NULL, 12),
  (900013, 'COMPLETED', 5.0, 1,  0, 'prior', 40,  0),
  (900014, 'WATCHING',  4.0, 14, 0, NULL,    NULL, 90),
  (900015, 'PLANNING',  NULL, 0, 0, NULL,    NULL, 0),
  (900016, 'COMPLETED', 4.5, 12, 0, 'this',  150, 10),
  (900017, 'COMPLETED', 3.0, 12, 0, 'this',  180, 21),
  (900018, 'COMPLETED', 4.0, 12, 0, 'prior', 210, 18),
  (900019, 'DROPPED',   1.5, 9,  0, NULL,    NULL, 400),
  (900020, 'COMPLETED', 4.5, 12, 0, 'this',  200, 7),
  (900021, 'PAUSED',    3.0, 11, 0, NULL,    NULL, 500),
  (900022, 'WATCHING',  NULL, 3, 0, NULL,    NULL, 20),
  (900023, 'PLANNING',  NULL, 0, 0, NULL,    NULL, 0),
  (900024, 'COMPLETED', 3.5, 12, 0, 'this',  230, 12),
  (900025, 'COMPLETED', 4.0, 24, 0, 'old',   90,  80),
  (900026, 'WATCHING',  3.5, 8,  0, NULL,    NULL, 30),
  (900027, 'PLANNING',  NULL, 0, 0, NULL,    NULL, 0),
  (900028, 'PLANNING',  NULL, 0, 0, NULL,    NULL, 0),
  (900029, 'PLANNING',  NULL, 0, 0, NULL,    NULL, 0),
  (900030, 'PLANNING',  NULL, 0, 0, NULL,    NULL, 0)
) AS v(anime_id, status, score, progress, repeat_count, finish_kind, finish_day, started_days)
CROSS JOIN LATERAL (
  SELECT CASE v.finish_kind
           WHEN 'this'  THEN LEAST(current_date, date_trunc('year', current_date)::date + v.finish_day)
           WHEN 'prior' THEN (date_trunc('year', current_date) - interval '1 year')::date + v.finish_day
           WHEN 'old'   THEN (date_trunc('year', current_date) - interval '3 years')::date + v.finish_day
         END AS finish
) AS f
WHERE u.email = :'email'
ON CONFLICT (user_id, anime_id) DO NOTHING;

-- ── Personal layer: notes, tags, moods, favourites, queue order ───────────
INSERT INTO personal_notes (user_id, anime_id, notes, personal_tags, mood_tags, favorite,
                            drop_reason, watch_next_priority)
SELECT u.id, v.anime_id, v.notes, v.tags::jsonb, v.moods::jsonb, v.fav, v.drop_reason, v.prio
FROM users u
CROSS JOIN (VALUES
  (900001, 'Funnier on the second watch. The episode with the stuck airlock is the best one.',
   '["comfort food","rewatch"]', '["funny","comfort"]', true, NULL, NULL),
  (900002, 'Cried at the lighthouse episode. Twice.',
   '["comfort food","favourite soundtrack"]', '["wholesome","bittersweet"]', true, NULL, NULL),
  (900005, 'Watched in one sitting. The drowned-city sequence is gorgeous.',
   '["movie night"]', '["bittersweet"]', NULL, NULL, NULL),
  (900007, NULL, '["background watching"]', '["hype"]', NULL,
   'Same joke every episode after episode three.', NULL),
  (900012, 'Second time through, watching with a friend.',
   '["comfort food","watch with friends"]', '["relaxing","comfort"]', true, NULL, NULL),
  (900013, 'The final concert scene lives rent-free in my head.',
   '["movie night","favourite soundtrack"]', '["thought_provoking"]', true, NULL, NULL),
  (900014, 'Weekly highlight. Keep up as it airs.',
   '["airing now"]', '["hype","intense"]', NULL, NULL, NULL),
  (900019, NULL, '[]', '[]', NULL, 'Too much baseball, not enough sea cats.', NULL),
  (900020, 'The reveal about the right clock is worth the slow start.',
   '["mind-bender"]', '["thought_provoking","intense"]', NULL, NULL, NULL),
  (900015, 'Recommended by a friend.', '["watch with friends"]', '[]', NULL, NULL, 2),
  (900023, NULL, '["summer"]', '[]', NULL, NULL, 1),
  (900030, 'Saving this for a slow weekend.', '["comfort food"]', '["relaxing"]', NULL, NULL, 3)
) AS v(anime_id, notes, tags, moods, fav, drop_reason, prio)
WHERE u.email = :'email'
ON CONFLICT (user_id, anime_id) DO NOTHING;

INSERT INTO rewatch_notes (user_id, anime_id, repeat_count, note)
SELECT u.id, v.anime_id, v.rc, v.note
FROM users u
CROSS JOIN (VALUES
  (900001, 1, 'Caught all the background gags I missed the first time.'),
  (900002, 1, 'Watched over a holiday week.'),
  (900002, 2, 'Showed it to my sister this time.'),
  (900012, 1, 'Slower pace this time; the cafe regulars are the point.')
) AS v(anime_id, rc, note)
WHERE u.email = :'email'
ON CONFLICT (user_id, anime_id, repeat_count) DO NOTHING;

INSERT INTO episode_notes (user_id, anime_id, episode_number, note, memorable_quote)
SELECT u.id, v.anime_id, v.ep, v.note, v.quote
FROM users u
CROSS JOIN (VALUES
  (900004, 3, 'The conductor knows more than he says.', NULL),
  (900004, 5, 'Best episode so far.', 'Every ticket is one way. That is the point.'),
  (900014, 12, 'Mid-season finale. The dragon came back.', 'Nobody retires a dragon.')
) AS v(anime_id, ep, note, quote)
WHERE u.email = :'email'
ON CONFLICT (user_id, anime_id, episode_number) DO NOTHING;

INSERT INTO collections (user_id, name, filters)
SELECT u.id, v.name, v.filters::jsonb
FROM users u
CROSS JOIN (VALUES
  ('Comfort rewatches', '{"tag": "comfort food", "status": "COMPLETED"}'),
  ('Top-rated films', '{"format": "MOVIE", "sort": "score"}')
) AS v(name, filters)
WHERE u.email = :'email'
ON CONFLICT (user_id, name) DO NOTHING;

INSERT INTO user_streaming_services (user_id, service)
SELECT u.id, s FROM users u CROSS JOIN unnest(ARRAY['Crunchyroll', 'Netflix']) AS s
WHERE u.email = :'email'
ON CONFLICT DO NOTHING;

-- ── Recommendations ───────────────────────────────────────────────────────
INSERT INTO recommendation_scores (user_id, anime_id, score, reason, source, diversity_rank)
SELECT u.id, v.anime_id, v.score, v.reason::jsonb, v.source, v.rank
FROM users u
CROSS JOIN (VALUES
  (900031, 8.6, '{"matched_genres": ["Sci-Fi", "Slice of Life"], "matched_tags": ["Gardening"], "matched_studio": "Studio Tetsubin"}', 'similarity', 1),
  (900032, 8.1, '{"matched_genres": ["Comedy", "Fantasy"], "matched_tags": ["Cooking"], "matched_studio": "Studio Kumo"}', 'seasonal', 2),
  (900033, 7.4, '{"matched_genres": ["Music", "Slice of Life"], "matched_tags": []}', 'similarity', 3),
  (900034, 6.9, '{"matched_genres": ["Mystery", "Sci-Fi"], "matched_tags": []}', 'similarity', 4),
  (900035, 6.2, '{"matched_genres": ["Fantasy", "Adventure"], "matched_tags": ["Desert"]}', 'similarity', 5),
  (900036, 5.8, '{"matched_genres": ["Comedy", "Supernatural"], "matched_tags": ["Workplace"]}', 'similarity', 6)
) AS v(anime_id, score, reason, source, rank)
WHERE u.email = :'email'
ON CONFLICT (user_id, anime_id) DO NOTHING;

-- ── Upcoming episodes (relative to now) ───────────────────────────────────
INSERT INTO airing_schedule_cache (anime_id, episode, airing_at)
SELECT v.anime_id, v.ep, date_trunc('hour', now()) + make_interval(hours => v.hours)
FROM (VALUES
  (900004, 7, 30), (900004, 8, 198), (900004, 9, 366),
  (900014, 15, 54), (900014, 16, 222), (900014, 17, 390),
  (900022, 4, 10), (900022, 5, 178),
  (900027, 1, 100), (900027, 2, 268),
  (900032, 6, 75)
) AS v(anime_id, ep, hours)
ON CONFLICT (anime_id, episode) DO NOTHING;

-- ── Sync history, so Settings and Admin show a working instance ───────────
INSERT INTO sync_log (user_id, run_at, type, status, entries_updated, trigger, steps)
SELECT u.id, now() - make_interval(hours => v.hours_ago), v.type, 'ok', v.n, v.trig, v.steps::jsonb
FROM users u
CROSS JOIN (VALUES
  (6,  'full_sync', 3, 'scheduled', '[{"service": "anilist_postgres", "status": "ok", "entries_updated": 3, "error_msg": null}]'),
  (30, 'full_sync', 1, 'scheduled', '[{"service": "anilist_postgres", "status": "ok", "entries_updated": 1, "error_msg": null}]'),
  (50, 'recommender', NULL, NULL, NULL)
) AS v(hours_ago, type, n, trig, steps)
WHERE u.email = :'email';

COMMIT;
